/* An INDEPENDENT check on the object-id known answers, and an anchor to the
 * constants git publishes rather than to the binary that produced them.
 *
 * git-objects.kat.json already pins fixed hex, which is the right shape. What
 * its own header records is where those bytes came from:
 *
 *   "Known-answer tests generated by the real git binary"  generatedBy 2.53.0
 *
 * That is reproduced from a validated implementation, not copied from a
 * publication -- exactly the distinction crypto-lab#31 warns about in its own
 * preamble: a cited source "does not establish that the values were copied from
 * that publication rather than reproduced from a validated implementation". If
 * the local git binary and this lab were ever wrong in the same direction, the
 * KAT would agree with both.
 *
 * So this file recomputes the ids a THIRD way: Node's crypto module -- a
 * different implementation from the WebCrypto that objects.ts uses -- applied
 * to the preimage format git DOCUMENTS, `<type> <size>\0<content>`. Agreement
 * between two implementations and a documented construction is a stronger
 * claim than agreement with one binary's output.
 *
 * It also anchors the two ids that are canonical published constants in their
 * own right, independent of any binary: git's empty blob and its empty tree.
 */
import { describe, expect, it } from 'vitest'
import { createHash } from 'node:crypto'

import KAT from './git-objects.kat.json'
import { hashBlob, hashObject, objectPreimage, utf8, type HashAlgo } from './objects'

/** The id git documents, computed from the documented preimage with node:crypto. */
function independentId(type: 'blob' | 'tree' | 'commit', content: Uint8Array, algo: HashAlgo): string {
  const header = Buffer.from(`${type} ${content.length}\0`, 'utf8')
  return createHash(algo).update(Buffer.concat([header, Buffer.from(content)])).digest('hex')
}

const ALGOS: readonly HashAlgo[] = ['sha1', 'sha256']

describe('a second implementation agrees with the known answers', () => {
  it('the empty blob, under both algorithms', async () => {
    for (const algo of ALGOS) {
      const independent = independentId('blob', new Uint8Array(0), algo)
      expect(independent).toBe(KAT.wellKnown[algo].emptyBlob)
      expect(await hashBlob('', algo)).toBe(independent)
    }
  })

  it('the "hello world" blob, under both algorithms', async () => {
    for (const algo of ALGOS) {
      const independent = independentId('blob', utf8('hello world\n'), algo)
      expect(independent).toBe(KAT.wellKnown[algo].helloWorldBlob)
      expect(await hashBlob('hello world\n', algo)).toBe(independent)
    }
  })

  it('the empty tree, under both algorithms', async () => {
    for (const algo of ALGOS) {
      const independent = independentId('tree', new Uint8Array(0), algo)
      expect(independent).toBe(KAT.wellKnown[algo].emptyTree)
      expect(await hashObject('tree', new Uint8Array(0), algo)).toBe(independent)
    }
  })

  /* The canonical constants, written out rather than read from the KAT, so this
     file would still catch a regenerated KAT that drifted. These two SHA-1 ids
     are published in git's own documentation and are stable across every git
     version; they are not this machine's binary talking. */
  it('matches the canonical published ids for the empty blob and empty tree', async () => {
    expect(await hashBlob('', 'sha1')).toBe('e69de29bb2d1d6434b8b29ae775ad8c2e48c5391')
    expect(await hashObject('tree', new Uint8Array(0), 'sha1'))
      .toBe('4b825dc642cb6eb9a060e54bf8d69288fbee4904')
  })
})

describe('the construction the ids rest on', () => {
  it('the preimage is exactly `<type> <size>\\0<content>`, byte for byte', () => {
    const content = utf8('hello world\n')
    expect(Buffer.from(objectPreimage('blob', content)))
      .toEqual(Buffer.concat([Buffer.from('blob 12\0', 'utf8'), Buffer.from(content)]))
  })

  it('the header is load-bearing: hashing the content alone gives a different id', async () => {
    const content = utf8('hello world\n')
    const withHeader = await hashBlob('hello world\n', 'sha1')
    const contentOnly = createHash('sha1').update(Buffer.from(content)).digest('hex')
    expect(withHeader).not.toBe(contentOnly)
    /* And the difference is the header, not the algorithm. */
    expect(withHeader).toBe(independentId('blob', content, 'sha1'))
  })
})
